    private final List<String> erroresSintacticos = new ArrayList<>();
    public Symbol ultimoError = null;

    public boolean tieneMain = false;
    public StringBuilder reportePrint = new StringBuilder();

    public void registrarErrorSemantico(String mensaje, int linea, int col) {
        reportePrint.append("Error Semántico [Línea: ").append(linea)
                    .append(", Columna: ").append(col).append("]: ")
                    .append(mensaje).append("\n");
    }

    public void registrarInfo(String mensaje) {
        reportePrint.append(mensaje).append("\n");
    }

    public List<String> getErroresSintacticos() {
        return erroresSintacticos;
    }

    private int linea(Symbol s) {
        return s == null ? -1 : s.left;
    }

    private int columna(Symbol s) {
        return s == null ? -1 : s.right;
    }

    private String ubicacion(Symbol s) {
        if (s == null) return "fin de entrada";
        return "línea " + linea(s) + ", columna " + columna(s);
    }

    @Override
    public void report_error(String message, Object info) {
        if (info instanceof Symbol s) {
            ultimoError = s;
            erroresSintacticos.add(
                "Error sintáctico en " + ubicacion(s) + ": " + message
            );
        } else {
            erroresSintacticos.add("Error sintáctico: " + message);
        }
    }

    @Override
    public void syntax_error(Symbol cur_token) {
        ultimoError = cur_token;
        if (cur_token != null) {
            erroresSintacticos.add(
                "Token inesperado '" + (cur_token.value != null ? cur_token.value : cur_token.sym)
                + "' en " + ubicacion(cur_token)
            );
        } else {
            erroresSintacticos.add("Error sintáctico: fin de entrada inesperado");
        }
    }

    @Override
    public void unrecovered_syntax_error(Symbol cur_token) throws Exception {
        ultimoError = cur_token;
        if (cur_token != null) {
            erroresSintacticos.add(
                "No se pudo recuperar del error en " + ubicacion(cur_token)
            );
        } else {
            erroresSintacticos.add("No se pudo recuperar del error al final de la entrada");
        }
        throw new Exception(
            "Error sintáctico irrecuperable en " +
            (ultimoError != null ? ubicacion(ultimoError) : "posición desconocida")
        );
    }


